// Кейс: .qa/tests/camera-aim/CAM-005.md · план: .qa/e2e-app/specs/app.md (1.51)
// Зона без воды (светлый/серый экран, бумага, клавиатура, стол): «לא זוהו מים באזור שסומן. כוונו את המצלמה לבריכה וסמנו את שטח המים.»,
// «המשך» серая даже с галочкой «כל שטח המים נראה…»; «זו הבריכה שלי» (раньше открывала «המשך») нет. Красные точки — визуально, вручную.
// РУЧНАЯ СЦЕНА (требует подготовки): камера iPhone на экран Mac с картинкой на весь экран: .qa/media/screen-white-bluish.png (светлый экран),
// .qa/media/surface-grey-cool.png (серая поверхность) или .qa/media/table-brown.png (стол) — либо физическая бумага/клавиатура/стол.
// BANCI_SCENE=no-water-light | no-water (иначе пропуск). Известная слабость (находка, не реджект, 08.11): насыщенно-циановая поверхность может пройти. Мониторинг НЕ запускается.
import { by, assert, skip, checkedFromValue } from '../../lib/appium.mjs';
import { openCameraStep, waitEnabled } from '../../lib/banci.mjs';

export const name = 'Шаг 2, светлая поверхность без воды: «לא זוהו מים…», «המשך» серая даже с галочкой, «זו הבריכה שלי» нет (ручная сцена BANCI_SCENE=no-water-light) #ab4270 @iphone @app @prod-safe';
const NO_WATER = 'לא זוהו מים באזור שסומן. כוונו את המצלמה לבריכה וסמנו את שטח המים.';

export default async function (app) {
  if (!['no-water-light', 'no-water'].includes(process.env.BANCI_SCENE)) skip('ручная сцена: на Mac на весь экран .qa/media/screen-white-bluish.png (или бумага/клавиатура/стол перед камерой) → BANCI_SCENE=no-water-light');

  const water = await openCameraStep(app);
  await app.waitFor(by.contains(NO_WATER), { timeout: 20000, what: `подсказка «${NO_WATER}» (нет — проверить сцену)` });
  assert(!(await app.exists(by.contains('זו הבריכה שלי'))), 'нет галочки «זו הבריכה שלי» (OTA c38476a1 не загрузился?)');
  if (checkedFromValue(await water.attr('value')) !== true) await water.click();
  const next = await app.waitFor(by.exact('המשך', 'Button'), { what: '«המשך» на шаге 2' });
  await waitEnabled(next, false, { timeout: 5000, what: '«המשך» на зоне без воды с галочкой' });
  assert(await app.exists(by.contains(NO_WATER)), 'подсказка «לא זוהו מים…» осталась после галочки');
  await app.screenshot('ab4270-light-no-water-blocked');
  await app.restart();
}
